import React, { useState } from 'react';
import './CSS/LoginSignup.css';

const LoginSignup = () => {
  const [state, setState] = useState("Login"); 
  const [formdata,setFormData] = use

  const login = async () => {
    console.log("Login Function Executed");
  };

  const signup = async () => {
    console.log("Signup Function Executed");
  };

  return (
    <div className='loginsignup'>
      <div className="loginsignup-container">
        <h1>{state}</h1>
        <div className="loginsignup-fields">
          {state === "Signup" ? <input type="text" placeholder='Your Name' /> : null}
          <input type="email" placeholder='Email Address' />
          <input type="password" placeholder='Password' />
        </div>
        
        {/* Pass the function reference directly */}
        <button onClick={state === "Login" ? login : signup}>Continue</button>
        
        {state === "Signup" ? (
          <p className="loginsignup-login">
            Already have an account? <span onClick={() => setState("Login")}>Login Here</span>
          </p>
        ) : (
          <p className="loginsignup-login">
            Create an account? <span onClick={() => setState("Signup")}>Click Here</span>
          </p>
        )}
        
        <div className="loginsignup-agree">
          <input type="checkbox" name='agree' id='agree' />
          <p>By continuing, I agree to the terms of use & privacy policy.</p>
        </div>
      </div>
    </div>
  );
};

export default LoginSignup;
